CREATE OR REPLACE PACKAGE table_stats AS
  FUNCTION summary(p_table_name IN VARCHAR2) RETURN VARCHAR2;
  FUNCTION column_stats(p_table_name IN VARCHAR2) RETURN VARCHAR2;
  FUNCTION histogram(p_table_name IN VARCHAR2, p_column_name IN VARCHAR2) RETURN VARCHAR2;
  FUNCTION report(p_table_name IN VARCHAR2) RETURN VARCHAR2;
  PROCEDURE show(p_table_name IN VARCHAR2);
END table_stats;
